CREATE TABLE IF NOT EXISTS leads (id TEXT PRIMARY KEY, created_at TEXT, source TEXT, business_name TEXT, owner_name TEXT, phone TEXT, city TEXT, area TEXT, category TEXT, maps_url TEXT, instagram_url TEXT, rating REAL, reviews INTEGER, address TEXT, stage TEXT DEFAULT 'new', score INTEGER DEFAULT 0, notes TEXT, shop_id TEXT, next_action_at TEXT);
CREATE TABLE IF NOT EXISTS consents (id TEXT PRIMARY KEY, lead_id TEXT, phone TEXT, channel TEXT, granted_at TEXT, granted_by TEXT, note TEXT, revoked_at TEXT);
CREATE TABLE IF NOT EXISTS shops (id TEXT PRIMARY KEY, slug TEXT UNIQUE, lead_id TEXT, name TEXT, tagline TEXT, category TEXT, status TEXT DEFAULT 'preview', expires_at TEXT, plan TEXT DEFAULT 'none', template_id TEXT, theme_json TEXT, logo_url TEXT, phone TEXT, whatsapp TEXT, email TEXT, maps_url TEXT, address TEXT, instagram TEXT, facebook TEXT, youtube TEXT, upi_id TEXT, upi_qr_url TEXT, created_at TEXT, paid_at TEXT, custom_domain TEXT);
CREATE TABLE IF NOT EXISTS sellers (id TEXT PRIMARY KEY, shop_id TEXT, name TEXT, phone TEXT UNIQUE, email TEXT, last_login_at TEXT, lang TEXT DEFAULT 'hinglish', push_token TEXT);
CREATE TABLE IF NOT EXISTS products (id TEXT PRIMARY KEY, shop_id TEXT, name TEXT, description TEXT, category TEXT, price INTEGER, mrp INTEGER, stock INTEGER, sold_out INTEGER DEFAULT 0, active INTEGER DEFAULT 1, attributes_json TEXT, created_at TEXT, source TEXT);
CREATE TABLE IF NOT EXISTS product_images (id TEXT PRIMARY KEY, product_id TEXT, shop_id TEXT, url TEXT, sort INTEGER, is_stock INTEGER DEFAULT 0);
CREATE TABLE IF NOT EXISTS product_variants (id TEXT PRIMARY KEY, product_id TEXT, shop_id TEXT, label TEXT, sku TEXT, stock INTEGER, price_delta INTEGER DEFAULT 0);
CREATE TABLE IF NOT EXISTS orders (id TEXT PRIMARY KEY, shop_id TEXT, number INTEGER, created_at TEXT, buyer_name TEXT, buyer_phone TEXT, buyer_email TEXT, address TEXT, pincode TEXT, city TEXT, state TEXT, subtotal INTEGER, shipping INTEGER, total INTEGER, payment_method TEXT, payment_status TEXT DEFAULT 'pending', payment_proof_url TEXT, utr TEXT, status TEXT DEFAULT 'placed', courier TEXT, tracking_id TEXT, tracking_url TEXT, dispatched_at TEXT, notes TEXT);
CREATE TABLE IF NOT EXISTS order_items (id TEXT PRIMARY KEY, order_id TEXT, shop_id TEXT, product_id TEXT, variant_id TEXT, name TEXT, qty INTEGER, price INTEGER);
CREATE TABLE IF NOT EXISTS order_events (id TEXT PRIMARY KEY, order_id TEXT, shop_id TEXT, at TEXT, type TEXT, detail TEXT);
CREATE TABLE IF NOT EXISTS templates (id TEXT PRIMARY KEY, category TEXT, name TEXT, version INTEGER, spec_json TEXT, preview_url TEXT);
CREATE TABLE IF NOT EXISTS preview_events (id TEXT PRIMARY KEY, shop_id TEXT, at TEXT, type TEXT, meta_json TEXT);
CREATE TABLE IF NOT EXISTS chat_messages (id TEXT PRIMARY KEY, shop_id TEXT, lead_id TEXT, at TEXT, direction TEXT, kind TEXT, body TEXT, wa_message_id TEXT);
CREATE TABLE IF NOT EXISTS bot_usage (id TEXT PRIMARY KEY, shop_id TEXT, day TEXT, ai_calls INTEGER, input_tokens INTEGER, output_tokens INTEGER, est_cost_paise INTEGER);
CREATE TABLE IF NOT EXISTS couriers (id TEXT PRIMARY KEY, name TEXT, tracking_url_template TEXT);
CREATE TABLE IF NOT EXISTS audit_log (id TEXT PRIMARY KEY, at TEXT, actor TEXT, action TEXT, target TEXT, meta_json TEXT);
CREATE INDEX IF NOT EXISTS idx_orders_shop ON orders(shop_id, created_at);
CREATE INDEX IF NOT EXISTS idx_products_shop ON products(shop_id, active);
CREATE INDEX IF NOT EXISTS idx_leads_stage ON leads(stage, score);
